Item.method_code:
            //送信先のアイデンティティを設定する
            Innovator inn = this.getInnovator();
            string sendIdentityName = CCO.Utilities.GetVarValue("h4_SystemOperator", "");
            Item identityItem = inn.getItemByKeyedName("Identity", sendIdentityName);

            //パラメータ情報を設定する
            Item paramItem = inn.newItem("temp");
            //URLリンク用の変換
            HttpRequest request = ((Aras.Server.Core.IOMConnection)serverConnection).CCO.Request;
            string scheme = request.Scheme;
            string pathBase = request.PathBase.Value ?? string.Empty;
            string arasUrlAliasName = pathBase.Split('/')[1];
            string host = request.Host.Host;
            string aliasURL = $"{scheme}://{host}/{arasUrlAliasName}/";
            aliasURL += "?StartItem=" + "ConversionTask:" + this.getID();
            paramItem.setProperty("StartItem", aliasURL);
            paramItem.setProperty("taskId", this.getID());

            //メールメッセージアイテムの取得する
            Item emailTemplateItem = inn.getItemByKeyedName("Email Message", "h4_MsgOfficeToConverterError");

            try
            {
                //アイデンティティに紐づくユーザにメールを送信する
                bool sendSuccess = paramItem.email(emailTemplateItem, identityItem);
            }
            catch (Aras.Server.Core.InnovatorServerException ex)
            {
                return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));
            }
            return this;
        }
